<style>
.hire-hint {
  position: absolute;
  z-index: 7;
  top: 0;
  right: 2rem;
  display: flex;
  align-items: center;
  gap: 0.2rem;
  color: var(--accent);
  pointer-events: none;
  /* rotate last so the tilt happens about the aside's own centre and the
     placement beside the button is unaffected */
  transform: translate(calc(100% + 0.6rem), calc(-100% - 0.78rem)) rotate(7deg);
}

.hire-hint__arrow path {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  /* keeps the stroke a constant weight however the svg is scaled */
  vector-effect: non-scaling-stroke;
}

.hire-hint__label path {
  fill: currentColor;
}

/* below this width the card leaves under 70px beside the button, which is not
   enough room for the aside without colliding or forcing sideways scroll */
@media (max-width: 1199px) {
  .hire-hint {
    display: none;
  }
}
</style>
